import numpy as np
from unittest.mock import MagicMock
from satpy.readers.li_base_nc import LiBaseNC

class MockLiBaseNC(LiBaseNC):
    def __init__(self):
        # Mocking __init__ because it probably does a lot
        self.internal_variables = {}
        self.transform_names = []
        self.current_ds_info = None

    def get_measured_variable(self, var_paths, fill_value=np.nan):
        self.last_var_paths = var_paths
        return np.array([1])

    def apply_transforms(self, data_array, ds_info):
        return data_array

def test_get_transformed_dataset_list_vname():
    reader = MockLiBaseNC()

    # Case 1: vname is a string, sname is None
    ds_info = {"variable_name": "var1"}
    reader.get_transformed_dataset(ds_info)
    assert reader.last_var_paths == "var1"

    # Case 2: vname is a list, sname is None
    ds_info = {"variable_name": ["var1", "var2"]}
    reader.get_transformed_dataset(ds_info)
    assert reader.last_var_paths == ["var1", "var2"]

    # Case 3: vname is a string, sname is provided
    ds_info = {"variable_name": "var1", "sector_name": "sector1"}
    reader.get_transformed_dataset(ds_info)
    assert reader.last_var_paths == "sector1/var1"

    # Case 4: vname is a list, sname is provided
    ds_info = {"variable_name": ["var1", "var2"], "sector_name": "sector1"}
    reader.get_transformed_dataset(ds_info)
    # This is where it should fail currently
    assert reader.last_var_paths == ["sector1/var1", "sector1/var2"], f"Expected ['sector1/var1', 'sector1/var2'], got {reader.last_var_paths}"

if __name__ == "__main__":
    try:
        test_get_transformed_dataset_list_vname()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

